   content:\\\\n      - \\\\\\\"Per held-out generator macro-F1 with CI\\\\\\\"\\\\n      - \\\\\\\"Horizontal line at overall LOGO mean (0.79)\\\\\\\"\\\\n      - \\\\\\\"Optional: per-class (gen-0/gen-1/gen-2+) breakdown\\\\\\\"\\\\n    placement: \\\\\\\"Results §5.1\\\\\\\"\\\\n    evidence: [plan-002-eval]\\\\n\\\\n  fig3_baseline_comparison:\\\\n    title: \\\\\\\"Comparison with Single-Detector Baselines\\\\\\\"\\\\n    type: \\\\\\\"forest plot (dot-with-CI)\\\\\\\"\\\\n    tool: matplotlib\\\\n    aspect_ratio: \\\\\\\"4:3\\\\\\\"\\\\n    data_source: plan-015-v2 (detector_baseline_results.json)\\\\n    content:\\\\n      - \\\\\\\"7-feature ensemble: 0.798 [0.786, 0.799]\\\\\\\"\\\\n      - \\\\\\\"Avg-LogProb: 0.765 [0.616, 0.820]\\\\\\\"\\\\n      - \\\\\\\"LD-Score: 0.721 [0.588, 0.770]\\\\\\\"\\\\n      - \\\\\\\"FastDetectGPT: 0.627 [0.511, 0.762]\\\\\\\"\\\\n      - \\\\\\\"Binoculars: 0.579 [0.405, 0.664]\\\\\\\"\\\\n    notes: \\\\\\\"Key message: ensemble has tight CI, single detectors have wide CI. Reliability advantage, not just mean.\\\\\\\"\\\\n    placement: \\\\\\\"Results §5.3\\\\\\\"\\\\n    evidence: [plan-015-v2]\\\\n\\\\n  fig4_downstream_negative:\\\\n    title: \\\\\\\"Downstream CLM Perplexity by Data Curation Strategy\\\\\\\"\\\\n    type: \\\\\\\"bar chart with error bars\\\\\\\"\\\\n    tool: matplotlib\\\\n    aspect_ratio: \\\\\\\"4:3\\\\\\\"\\\\n    data_source: plan-004-v2\\\\n    content:\\\\n      - \\\\\\\"5 variants: all / size_matched / depth01 / binary_filtered / depth0_only\\\\\\\"\\\\n      - \\\\\\\"Y-axis: eval perplexity\\\\\\\"\\\\n      - \\\\\\\"Error bars: 3-seed variance\\\\\\\"\\\\n      - \\\\\\\"Annotation: data count per variant\\\\\\\"\\\\n    notes: \\\\\\\"Frame as honest negative. Title should not hide the negative result.\\\\\\\"\\\\n    placement: \\\\\\\"Results §5.4\\\\\\\"\\\\n    evidence: [plan-004-v2]\\\\n\\\\n##############################################################################\\\\n# 6