lan-001-fix, plan-014]\\\\n\\\\n  table3_downstream:\\\\n    title: \\\\\\\"Downstream CLM Fine-tuning by Depth Curation Strategy\\\\\\\"\\\\n    placement: \\\\\\\"Results §5.4\\\\\\\"\\\\n    columns: [\\\\\\\"Curation Strategy\\\\\\\", \\\\\\\"Train Size\\\\\\\", \\\\\\\"Eval PPL (mean±std)\\\\\\\", \\\\\\\"Δ vs size_matched\\\\\\\"]\\\\n    rows:\\\\n      - [\\\\\\\"All depths (no filter)\\\\\\\", \\\\\\\"12,299\\\\\\\", \\\\\\\"2.335 ± 0.000\\\\\\\", \\\\\\\"-0.032\\\\\\\"]\\\\n      - [\\\\\\\"Size-matched random\\\\\\\", \\\\\\\"3,951\\\\\\\", \\\\\\\"2.367 ± 0.000\\\\\\\", \\\\\\\"baseline\\\\\\\"]\\\\n      - [\\\\\\\"Depth 0+1 only\\\\\\\", \\\\\\\"3,951\\\\\\\", \\\\\\\"2.387 ± 0.001\\\\\\\", \\\\\\\"+0.020\\\\\\\"]\\\\n      - [\\\\\\\"Binary filtered\\\\\\\", \\\\\\\"3,951\\\\\\\", \\\\\\\"2.389 ± 0.000\\\\\\\", \\\\\\\"+0.022\\\\\\\"]\\\\n      - [\\\\\\\"Depth 0 only\\\\\\\", \\\\\\\"797\\\\\\\", \\\\\\\"2.681 ± 0.001\\\\\\\", \\\\\\\"+0.314\\\\\\\"]\\\\n    footer: >\\\\n      OLMo-2-0425-1B, 3 seeds. Size-matched is the proper control.\\\\n      Depth-aware curation does not outperform random subsampling at equal data count.\\\\n    evidence: [plan-004-v2]\\\\n\\\\n  table4_cross_ref:\\\\n    title: \\\\\\\"Cross-Family Reference Model Validation\\\\\\\"\\\\n    placement: \\\\\\\"Appendix (or Results §5.2 if space)\\\\\\\"\\\\n    columns: [\\\\\\\"Reference Model\\\\\\\", \\\\\\\"Family\\\\\\\", \\\\\\\"Params\\\\\\\", \\\\\\\"LOGO F1\\\\\\\", \\\\\\\"Entropy Drift Range\\\\\\\"]\\\\n    rows:\\\\n      - [\\\\\\\"Pythia-410M\\\\\\\", \\\\\\\"Pythia\\\\\\\", \\\\\\\"410M\\\\\\\", \\\\\\\"0.803\\\\\\\", \\\\\\\"[-1.19, -1.40]\\\\\\\"]\\\\n      - [\\\\\\\"OLMo-2-1B\\\\\\\", \\\\\\\"OLMo\\\\\\\", \\\\\\\"1.5B\\\\\\\", \\\\\\\"0.807\\\\\\\", \\\\\\\"[-0.61, -0.91]\\\\\\\"]\\\\n      - [\\\\\\\"Qwen3-0.6B\\\\\\\", \\\\\\\"Qwen\\\\\\\", \\\\\\\"0.6B\\\\\\\", \\\\\\\"0.816\\\\\\\", \\\\\\\"[-0.96, -1.35]\\\\\\\"]\\\\n    footer: \\\\\\\"Drift direction consistent across all reference models; magnitude varies.\\\\\\\"\\\\n    evidence: [plan-003]\\\\n\\\\n##############################################################################\\\\n# 7. Literature Strategy\\\\n##############################################################################\\\\n\\\\nliterature:\\\\n  total_papers: 39\\\\n  organization:\\\\n    perplexity_detection:\\\\n      papers: 16\\\\n      key_refs: [detectgpt, fast_detectgpt, binoculars, ld_score, diveye, generator_barrier]\\\\n      positioning: \\\\\\\"Binary detection paradigm. No depth estimation. High cross-generator variance when repurposed as ordinal predictors.\\\\\\\"\\\\n    model_collapse:\\\\n      papers: 4\\\\n      key_refs: [curse_of_recursion, strong_model_collapse, self_consuming_mad]\\\\n      positioning: \\\\\\\"Training-loop collapse. We study inference chains without retraining — distributional drift without model parameter change.\\\\\\\"\\\\n    iterative_generation:\\\\n      papers: 2\\\\n      key_refs: [broken_telephone, markovian_chains]\\\\n      positioning: \\\\\\\"Most directly related. broken_telephone: paraphrasing/translation chains. markovian_chains: convergence theory. We: non-paraphrastic continuation chains + depth estimation task.\\\\\\\"\\\\n    vocabulary_diversity:\\\\n      papers: 5\\\\n      key_refs: [curious_decline, writing_diversity, nucleus_sampling]\\\\n      positioning: \\\\\\\"Diversity decline documented in training loops. We show it appears in inference chains too and use it for depth classification.\\\\\\\"\\\\n    stylometry:\\\\n      papers: 3\\\\n      key_refs: [stamatatos_survey, uchendu_attribution]\\\\n      positioning: \\\\\\\"Feature set is essentially stylometric. We extend from source attribution to depth estimation.\\\\\\\"\\\\n    data_quality:\\\\n      papers: 3\\\\n      key_refs: [dsir, qurating]\\\\n      positioning: \\\\\\\"Data scoring/selection. Depth fingerprint as complementary provenance signal.\\\\\\\"\\\\n    watermarking:\\\\n      papers: 4\\\\n      key_refs: [watermark_llm, chainwash]\\\\n      positioning: \\\\\\\"Active signal embedding. We: passive post-hoc detection without watermark. chainwash motivates depth-aware approach — watermarks decay over generation steps.\\\\\\\"\\\\n    membership_inference:\\\\n      papers: 1\\\\n      key_refs: [min_k_percent]\\\\n      positioning: \\\\\\\"Probability distribution analysis for membership; we analyze for depth.\\\\\\\"\\\\n    ood_detection:\\\\n      papers: 1\\\\n      key_refs: [ood_baseline]\\\\n      positioning: \\\\\\\"Reference-model entropy features are functionally NLL-based OOD scores. Explicitly acknowledge this connection (RC8).\\\\\\\"\\\\n\\\\n##############################################################################\\\\n# 8. Writing Order & Dependencies\\\\n##############################################################################\\\\n\\\\nwriting_order:\\\\n  phase1_skeleton:\\\\n    deadline: \\\\\\\"2026-05-18\\\\\\\"\\\\n    tasks:\\\\n      - section: \\\\\\\"Results (§5)\\\\\\\"\\\\n        reason: \\\\\\\"Anchor claims to evidence first. Numbers drive the narrative.\\\\\\\"\\\\n        dependencies: []\\\\n        priority: 1\\\\n      - section: \\\\\\\"Method (§4)\\\\\\\"\\\\n        reason: \\\\\\\"Experimental setup needed to interpret results.\\\\\\\"\\\\n        dependencies: []\\\\n        priority: 2\\\\n      - section: \\\\\\\"Figures (all 4)\\\\\\\"\\\\n        reason: \\\\\\\"Figures convey results more effectively than text. Generate early.\\\\\\\"\\\\n        dependencies: [\\\\\\\"Results\\\\\\\"]\\\\n        priority: 1\\\\n\\\\n  phase2_narrative:\\\\n    deadline: \\\\\\\"2026-05-21\\\\\\\"\\\\n    tasks:\\\\n      - section: \\\\\\\"Introduction (§1)\\\\\\\"\\\\n        reason: \\\\\\\"Story spine. Requires stable results to write convincingly.\\\\\\\"\\\\n        dependencies: [\\\\\\\"Results\\\\\\\"]\\\\n        priority: 1\\\\n      - section: \\\\\\\"